        text: "現代的なカフェ、観光複合施設、大学周辺の学生の集い、そしてSNS——サマルカンドの若者文化には、伝統的なチャイハナ文化とはひと味違う、新しい都市の息吹があふれています。コワーキングやIT産業が牽引する首都タシュケントとは異なり、観光と学問に支えられているのがこの街らしさです。それでいて、家族や地域を大切にする心は変わらず受け継がれています。旅の合間に、そんな「今」のサマルカンドも味わってみてください。",
