        text: "カラーン・ミナレットは、ブハラ旧市街の空にひときわ高くそびえる大尖塔で、街のどこからでも見上げられるブハラの象徴です。このミナレットを中心に、カラーン・モスクとミル・アラブ・メドレセが向かい合って建つ一帯は「ポイ・カリャン（偉大なるものの足元）」と呼ばれる複合施設を形づくっています。ブハラ旧市街全体の見どころは別記事「ブハラ旧市街の観光スポットガイド」で紹介していますが、この記事ではその中心にあるカラーン・ミナレットとポイ・カリャンにしぼって、見どころを詳しくまとめます。",
