        text: "ブハラの結婚式をとりわけ華やかに彩るのが、衣装です。花嫁は西洋風のウェディングドレスを着ることも多い一方、伝統的な場面では、鮮やかな色彩と細やかな刺繍がほどこされた民族衣装をまとうこともあります。ブハラは金糸刺繍（ズラバフ）の名産地として知られ、かつては宮廷の装束や礼服を彩ったこの豪華な刺繍が、祝いの席の装いにいっそうの格調を添えます。金糸・銀糸をふんだんに使ったビロードの衣装や小物は、職人の街ブハラならではの晴れやかさです。参列者もまた色とりどりの装いで集い、会場は華やかな彩りで埋め尽くされます。",
