        type: "paragraph",
        text: "ブハラの結婚式のもうひとつの特徴は、地域ぐるみで祝う点にあります。準備の段階から旧市街のマハッラの人々が集まって料理を仕込み、会場を整え、当日は招待客の対応を分担します。一つの家庭だけでは到底担いきれない大規模な祝宴を、近隣の助け合いによって成り立たせているのです。狭い路地で家々が寄り添うように暮らすこの街では、そうした結束がとりわけ自然な形で表れます。結婚式は二人の門出であると同時に、地域全体の絆を確かめ合う場でもあるのです。もてなしを惜しまないこの国の価値観が、祝宴のすみずみにまで息づいています。",
