        text: "観光とともに生きる暮らしは、季節の波と切り離せません。ヒヴァでは、気候の穏やかな春（4〜5月）と秋（9〜10月）が観光の最盛期で、この時期には城壁の内側が旅行者でにぎわい、観光に携わる住民も忙しく働きます。一方、40度を超える真夏や、冷え込む冬は旅行者が減り、街は静けさを取り戻します。こうした繁忙期と閑散期の落差のなかで、人々は稼ぎ時にしっかり働き、閑散期には家の手入れや家族との時間、次の季節への備えに充てるといったリズムで暮らしています。観光の季節性は、ヒヴァの住民の一年の過ごし方そのものを形づくっているのです。",
