        type: "paragraph",
        text: "ヒヴァは、木彫刻をはじめとする伝統工芸が息づく街でもあります。ジュマ・モスクの木彫り柱に代表される精緻な木工の技は、今も職人たちの手で受け継がれ、その多くが観光客への販売を通じて支えられています。旅行者が作り手から直接作品を買えることは、職人の生計を助けるだけでなく、廃れかけた技を次代へつなぐ力にもなっています。一方で、安価な既製品との競争や、時間のかかる本物の手仕事をどう続けるかという課題もあります。目の前で職人が刃を入れる姿を見られることは、ヒヴァならではの魅力であり、作り手の顔が見える買い物は、旅行者にあたたかな体験をもたらしてくれます。",
