        text: "ファルガナ渓谷の食べ物のお土産は、干しあんずやレーズン、ナッツ、蜂蜜など、渓谷の恵みを一年中楽しめる形にした魅力的な品ぞろえです。土産として選ぶときは、まず日持ちを重視し、量り売りで味を確かめ、小分けとパッケージ、梱包、検疫まで見通して選ぶのがコツです。旅先で味わった渓谷の甘みを、持ち帰りやすい形で日本の家族や友人へ届ければ、旅の楽しさを分かち合えます。生の果物の味わいはグルメ記事とあわせて、土産選びの参考にしてください。",
