        text: "農村の一年で最も慌ただしいのが、秋の収穫期です。とりわけ綿花の摘み取りや、傷みやすい果実の収穫は、限られた時期に一気に作業を進める必要があり、一軒だけでは手が足りません。そこで力を発揮するのが、地域の助け合いです。近隣の人々が力を合わせて収穫を担う共同労働の習わし（ハシャル）のもと、家族や親族、ご近所が総出で畑や果樹園に集い、朝から日暮れまで手を動かします。収穫を終えたあとには皆で食卓を囲み、労をねぎらい合うのも習わしです。実りの季節に人々が力を合わせる光景は、渓谷の暮らしを支える共同体の結束を、もっともよく映し出しています。",
