        text: "かつてのアラル海は世界有数の大きさを誇る内陸湖で、アムダリヤとシルダリヤ（シル川）の水を集め、多様な魚が生息する豊かな漁場でした。川と湖が交わるデルタ地帯には葦原や湿地が広がり、コイやフナ、スズキの仲間、ナマズなど、さまざまな魚が獲れました。カラカルパク人をはじめとする沿岸の人々にとって、魚は身近なたんぱく源であり、漁は暮らしの一部でした。砂漠の民でありながら水辺の恵みを受けてきたという二面性が、この地の食文化を特別なものにしています。",
